import type { HelpTopic, HelpImage, Parameter } from "../topics";

const shot = (path: string, caption: string): HelpImage => ({ path: `reference/${path}.png`, caption });
const feather: Parameter = ["Weiche Kante", "Macht die Begrenzung weich. 0 ergibt eine harte Kante und ist die Voreinstellung für neue Werkzeuge; 1 nutzt den gesamten verfügbaren Übergangsbereich. Ein Modifikator blendet seine Wirkung zum unveränderten Feld hin aus; ein Malwerkzeug blendet seinen Beitrag aus. Vorhandene Objekte behalten ihren gespeicherten Wert."];
const edge: Parameter = ["Rand: Überblenden / Ersetzen", "Überblenden mischt den neuen Vektor über einen weichen Rand mit dem vorhandenen. Ersetzen blendet den neuen Vektor stattdessen zur Stille hin aus. Der harte Innenbereich verwendet in beiden Modi den neuen Vektor. Undefinierte Quellzellen bleiben in beiden Modi transparent."];
const size: Parameter = ["Größe und Einheiten", "Pinseldurchmesser oder Quadratbreite. px ergibt beim Erstellen gleichbleibende Bildschirmproportionen; km / nm ergibt eine Entfernung über Grund. Späteres Zoomen ändert die Größe vorhandener Objekte nicht. Die gewählte Einheit gilt auch für die übrigen Größenregler des Werkzeugs."];
const brushShape: Parameter = ["Pinselform: Kreis / Quadrat", "Wählt den Stempel, der entlang der Geste gezogen wird. Kreis ergibt runde Enden; Quadrat zieht quadratische Stempel. Diese Geometrie ist nach dem Zeichnen festgelegt; eine Formanimation kann ein vorhandenes Objekt umformen."];
const speed: Parameter = ["Geschwindigkeit", "Vektorbetrag in der globalen Geschwindigkeitseinheit. Null malt definierte Stille, was etwas anderes ist als ein leerer Bereich."];
const direction: Parameter[] = [
  ["Richtungsmodus", "Konstant verwendet eine einzige Kompassrichtung. Auf einen Punkt zu richtet jeden Ort einzeln auf ein Ziel aus; Von einem Punkt weg kehrt diese Richtung um. Es werden nur zutreffende Optionen angezeigt."],
  ["Richtung", "Grad in der Konvention „aus“ / „nach“ des Projekts. Norden ist 0°, Osten 90°, Süden 180°, Westen 270°. Bei Wind „aus“ malt 270° einen nach Osten wehenden Wind."],
  ["Ziel / Auf der Karte wählen", "Geben Sie Länge und dann Breite ein oder klicken Sie auf Auf der Karte wählen und dann auf das Ziel. Positive Länge ist Ost, positive Breite ist Nord. Dieser Klick setzt das Ziel, statt zu malen."],
  ["Richtung zum Ziel: Großkreis / Loxodrome", "Großkreis verwendet die örtliche Peilung der kürzesten Route auf der Kugel. Loxodrome verwendet einen konstanten Kompasskurs zum Ziel. Auf langen Routen und in hohen Breiten können beide deutlich voneinander abweichen."],
  ["Winkel relativ zum Ziel", "Versetzt die resultierende Richtung um −180° bis +180°. Null zielt direkt auf das Ziel zu oder von ihm weg. Positive Winkel drehen im Uhrzeigersinn, negative gegen den Uhrzeigersinn."],
];
const eyedropper: Parameter = ["Pipette", "Klicken Sie darauf und dann auf eine definierte Stelle der Karte, um Geschwindigkeit und Richtung in das Werkzeug zu übernehmen. Sie tastet sichtbare Daten der aktiven Feldart ab. Sie steht für Modi mit einem einzelnen Vektor zur Verfügung, nicht für Verläufe mit zwei Enden."];
const modifier = "Ein Bearbeitungsobjekt verändert die Daten unter ihm in seiner eigenen Ebene. Es kann keine Strömung über undefinierten Daten erzeugen. Platzieren Sie es über den Objekten, auf die es wirken soll. Transformation, Stärke, Lebensdauer und unterstützte Eigenschaften lassen sich animieren.";

/** Die mitgelieferte Offline-Referenz. Werte in Bildschirmfotos sind Beispiele, keine Voreinstellungen. */
const topics: HelpTopic[] = [
  { id: "workspace", group: "Arbeitsbereich", title: "Erste Schritte", paragraphs: [
    "VectorEffects erzeugt animierte Wind- und Oberflächenströmungsfelder aus gemalten Objekten, GRIB-Dateien, historischen Archiven und aufgenommenen Makros. Die Arbeitsfläche besitzt die Basiskarte. Leere Ebenen sind transparent; nur definierte Daten und Bildüberlagerungen verdecken, was darunter liegt.",
    "Diese durchsuchbare Referenz funktioniert offline. Wählen Sie links eine Seite und klicken Sie auf Bildschirmfotos, um sie in voller Größe anzusehen. Die Bildschirmfotos zeigen Beispielprojekte aus einer früheren Beta: Werte ungleich null bei der weichen Kante sind Beispiele, der Winkel des Kreises verwendet jetzt einen Schieberegler, und die frühere Option Absolut der Kurve heißt jetzt Konstant.",
  ], steps: ["Wählen Sie Neu… und legen Sie Auflösung, Zeitschritt und Schritte fest.", "Wählen Sie eine nicht gesperrte Ebene, dann Pinsel, stellen Sie Geschwindigkeit und Richtung ein und ziehen Sie auf der Karte.", "Wählen Sie das neue Objekt aus, um es zu prüfen oder zu animieren.", "Speichern Sie als .veproj, um die Objekte bearbeitbar zu halten. Mit GRIB exportieren… erhalten Sie Vektordaten für andere Programme."],
    images: [shot("overview/overview", "Karte, Werkzeugoptionen, Ebenen, Eigenschaften, Verlauf und Zeitleiste.")], related: ["projects", "tools", "layers", "animation", "export"] },
  { id: "projects", group: "Arbeitsbereich", title: "Projekte, Speichern und Wiederherstellung", paragraphs: ["Über das Menü Projekt in der Titelleiste erreichen Sie Neu, Öffnen, Speichern, Speichern unter und Schließen. Ein Projekt speichert Gitter, Zeitleiste, Ebenen, Geometrie und Animation. Lassen Sie importierte Quelldateien an ihren referenzierten Pfaden, wenn Sie ein Projekt erneut öffnen oder verschieben. Bewahren Sie die .veproj-Datei nach dem Export als bearbeitbares Original auf."],
    parameters: [["Neu: Name", "Benennt das Projekt. Die Feldart jeder gemalten Ebene legen Sie im Ebenenbedienfeld fest."], ["Auflösung", "Geografischer Gitterabstand. Ein feineres Gitter löst kleinere Details auf, erhöht aber Berechnungszeit und Exportgröße."], ["Zeitschritt / Schritte", "Simulierte Stunden zwischen den Bildern und Gesamtzahl der Bilder. Sie sind unabhängig von den Wiedergabebildern pro Sekunde."], ["Öffnen / Zuletzt verwendet", "Öffnet eine .veproj-Datei. Die Liste Zuletzt verwendet zeigt vorhandene Dateien; mit Durchsuchen… finden Sie ein verschobenes Projekt."], ["Speichern / Speichern unter", "Speichern aktualisiert die aktuelle Datei. Speichern unter wählt einen neuen Pfad. Ein ungespeichertes Projekt braucht zuerst einen Pfad."], ["Schließen", "Schließt das Projekt. Bei ungespeicherter Arbeit werden Speichern, Nicht speichern oder Abbrechen angeboten."], ["Automatisches Speichern", "In den Einstellungen können Sie Momentaufnahmen zur Wiederherstellung anlegen, direkt in die Projektdatei speichern oder manuell speichern. Ausgelöst wird jede Minute oder alle fünfzig Änderungen, je nachdem, was zuerst eintritt. Nach einem Absturz wird die Wiederherstellung angeboten."], ["Rückgängig / Wiederholen / Verlauf", "Macht Änderungen am Dokument rückgängig oder wiederholt sie; der Verlauf beschreibt sie. Eine abgeschlossene Geste ist eine Änderung, sodass ein Rückgängig einen Strich entfernt oder einen radierten Bereich wiederherstellt."]],
    images: [shot("overview/project_management", "Projektsteuerung und das Zahnrad der Einstellungen.")], related: ["settings", "export", "troubleshooting"] },
  { id: "view", group: "Arbeitsbereich", title: "Kartenansicht und Richtungskonventionen", paragraphs: ["Verschieben Sie die Karte mit dem Hand-Werkzeug und zoomen Sie mit Mausrad oder Trackpad. Ansichtseinstellungen betreffen die Darstellung, nicht die exportierten Vektoren."],
    parameters: [["Aufnahme", "Startet den Makro-Aufnahmemodus, um einen Bereich über mehrere Bilder aufzuzeichnen."], ["Messen", "Öffnet Entfernungsringe, Stechzirkel, Routenvergleiche und die Verlagerungsgeschwindigkeit. Messungen malen keine Vektordaten."], ["Symbole", "Zeigt oder verbirgt Richtungen: meteorologische Windfiedern für Wind und Pfeile für Strömungen."], ["Projektion", "Durchsuchen Sie 270 Ansichten nach Name, Land oder EPSG-Code: Zylinder- und Weltkarten, einen orthografischen Globus, azimutale Karten, Polargitter für Nord und Süd, Landesgitter und jede UTM-Zone in WGS84. Regionale Karten passen sich ihrem Anwendungsbereich an; Ziehen an einem Globus oder einer azimutalen Karte verändert deren Mittelpunkt. Eigene Projektion akzeptiert PROJ, WKT oder einen mitgelieferten EPSG-Code. Die Definitionen funktionieren offline; Korrekturgitter für geodätische Datumsübergänge sind nicht enthalten. Dies ändert die Ansicht, nicht die gespeicherten Daten oder Exporte. In gekrümmten Ansichten werden Pixelgrößen am Startpunkt der Geste in Geometrie über Grund umgerechnet."], ["Gradnetz", "Zeigt Längen- und Breitenlinien zur Orientierung."], ["Auto-Skala", "Passt jede Farbskala an die sichtbaren Daten an: die Geschwindigkeiten von Wind und Strömung und die Meeresoberflächentemperaturen. Für Vergleiche mit festen Skalen ausschalten."], ["Legende", "Zeigt Farbverlauf, Feldart, Geschwindigkeitseinheit und Skalengrenzen."], ["Anzeige", "Zeigt Zeigerkoordinaten, abgetastete Geschwindigkeit und Richtung sowie den Zoom. „Kein Feld“ bedeutet undefinierte Daten."], ["Pfeile oder Windfiedern", "Ein Pfeil zeigt, wohin die Strömung geht. Eine Windfieder zeigt dorthin, woher der Wind kommt, mit den Fiedern an diesem Ende. Die Windfieder eines Nordwinds zeigt nach Norden, die Luft strömt aber nach Süden. Die numerische Richtungskonvention kehrt meteorologische Windfiedern nicht um."]],
    images: [shot("overview/view_and_global_settings", "Aufnahme, Messen, Rückgängig/Wiederholen und die Anzeigeoptionen der Karte.")], related: ["targets", "settings", "measure", "divergence"] },
  { id: "layers", group: "Arbeitsbereich", title: "Ebenen, Stapelung und Geschwindigkeitsfilter", paragraphs: ["Die Liste zeigt die Oberseite des Stapels zuerst. Gemalte Ebenen enthalten Objekte und sind vollständig transparent, wo diese Objekte keine Daten definieren. Die Basiskarte liegt unter dem Stapel und hat keine eigene Ebenenzeile. Sie können jede Ebene löschen; fügen Sie eine neue Ebene hinzu, um weiterzumalen, oder stellen Sie eine mit Rückgängig wieder her."],
    parameters: [["+ / Importieren / Kalender / Schüssel", "Fügt eine gemalte Ebene hinzu; importiert eine GRIB2-Datei, einen Routing-Zarr-Speicher, ein Bild oder GIS-Daten; oder lädt historische Daten herunter. Die Schüssel holt die letzten Tage beobachteter Daten."], ["Name / Aufklappdreieck", "Wählt die Ebene aus oder klappt ihre Objektliste auf."], ["Ziehgriff / Pfeile nach oben und unten", "Ordnet Ebenen neu, indem Sie ihre Köpfe ziehen oder die Pfeile verwenden. Ziehen Sie Objektzeilen, um sie neu zu ordnen, oder auf eine andere Ebene, um sie zu verschieben. Bearbeitungs- und Kopierstempelobjekte lesen, was in dieser Ebene unter ihnen liegt."], ["Auge / Schloss", "Blendet eine Ebene aus oder sperrt ihre Objekte gegen Bearbeitung. Entsperren Sie sie vor dem Zeichnen oder Transformieren."], ["Feld", "Wählt die Art gemalter Ebenen. Importierte Ebenen melden die Art ihrer Quelle. Wind und Strömung bleiben getrennte Felder."], ["Geschwindigkeitsfilter: kleinste / größte behaltene Geschwindigkeit", "Aktiviert einen einschließenden Geschwindigkeitsbereich in den Anzeigeeinheiten. Werte außerhalb werden transparent. Der Filter wird nach den Objekten und Bearbeitungen der Ebene angewendet; alle Ebenenarten unterstützen ihn. Bildschwellen verwenden die Vektorgeschwindigkeit an den Bildpositionen."], ["Duplizieren / ×", "Dupliziert ein Objekt, löscht ein Objekt oder löscht eine Ebene samt ihren Objekten. Rückgängig stellt Löschungen im Dokument wieder her."]],
    images: [shot("overview/layer_panel", "Ebenensteuerung und der optionale Geschwindigkeitsfilter.")], related: ["selection", "imports", "history", "clone"] },
  { id: "selection", group: "Arbeitsbereich", title: "Auswahl, Eigenschaften und Transformationen", paragraphs: ["Wählen Sie im Ebenenbedienfeld oder mit dem Auswahlwerkzeug aus; Umschalt-Klick erweitert die Auswahl. Nur ausgewählte Objekte erscheinen in der Bewegungsvorschau, auch wenn andere Objekte ihre Begrenzung überlappen. Das Wählen einer Ebene oder das Zeichnen eines Bereichs kann den Umfang der Auswahl ändern."],
    parameters: [["Position / Wählen", "Länge und Breite des Ankers. Wählen übernimmt sie aus einem Klick auf die Karte. Ziehen verschiebt den Anker; Schlüssel auf Position lassen ihn wandern."], ["Skalierung", "Ändert die Größe um den Anker. 100 % ist die Originalgröße. Sie ändert die Geometrie, nicht die Vektorgeschwindigkeit."], ["Drehung", "Dreht das Objekt und sein Feld um den Anker. Das Bearbeitungswerkzeug Strömung drehen dreht dagegen die Vektoren, ohne die Grundfläche des Felds zu bewegen."], ["Sichtbar", "Aktiviert das Objekt; setzen Sie Schlüssel, um es im Zeitverlauf ein- und auszuschalten."], ["Transformationsgriffe", "Verschieben, drehen oder skalieren die Auswahl im aktuellen Bild nach den Regeln für Schlüsselbilder."], ["Eigenschaftsrauten", "Fügen im ausgewählten Bild einen Schlüssel hinzu. Die Zeitleiste zeigt dieselben Eigenschaften und ihre Schlüssel."], ["Ebenendetails", "Ist kein Objekt ausgewählt, beschreiben die Eigenschaften die aktive Ebene: Quelle, Datei oder Archiv, Feldart und abgedeckte Bilder."], feather, edge],
    images: [shot("overview/properties_history", "Objekteigenschaften, Animationsrauten und Bearbeitungsverlauf.")], related: ["animation", "shape", "tools"] },
  { id: "tools", group: "Erstellwerkzeuge", title: "Werkzeuggrundlagen: Größe, weiche Kante und Ränder", paragraphs: ["Werkzeugoptionen gelten für neue Gesten; in den Eigenschaften bearbeiten Sie vorhandene Objekte. Nach dem Ändern einer Option verwendet der nächste Klick auf die Karte das Werkzeug. Auf der Karte wählen und die Pipette reservieren einen Klick bewusst für das Wählen oder Abtasten.", "Eine abgeschlossene Geste wird zu einem Objekt; passende Striche können je nach aktivem Werkzeug und Einstellungen zusammengeführt werden. Erstellwerkzeuge malen Vektoren, Bearbeitungswerkzeuge verändern die Daten unter ihnen. Es werden nur Optionen angezeigt, die im aktuellen Modus sinnvoll sind."],
    parameters: [size, brushShape, feather, edge, eyedropper, ["Pixelgeometrie", "px bedeutet Pixel beim Erstellen, auch in hohen Breiten. Die gespeicherte Geografie bleibt verankert, wenn Sie verschieben, zoomen oder die Projektion wechseln."], ["Feste Geometrieentscheidungen", "Entscheidungen wie die ursprüngliche Stempelform sind nach dem Erstellen festgelegt. Verwenden Sie eine Formanimation, um das Objekt umzuformen, statt seinen Konstruktionsmodus zu ändern."]],
    images: [shot("overview/tool_bar", "Hand, Auswählen, Radieren, Makro einfügen, Pinsel, Kreis, Formfüllung, Kopierstempel, Kurve, Maske, Verstärken / Abschwächen, Divergieren / Konvergieren, Strömung drehen, Verformen und Verschieben.")], related: ["brush", "circle", "path", "eraser"] },
  { id: "brush", group: "Erstellwerkzeuge", title: "Pinsel", paragraphs: ["Ziehen Sie, um einen gezogenen Kreis oder ein Quadrat zu malen; klicken Sie für einen einzelnen Stempel. Verwenden Sie eine konstante Strömung oder richten Sie jeden Vektor auf ein Ziel zu oder von ihm weg aus. Der Rand folgt Weiche Kante und Rand."],
    parameters: [brushShape, size, speed, ...direction, feather, edge, eyedropper],
    images: [shot("create_tools/brush_tool_constant", "Ein Pinsel mit konstanter Windrichtung. Die weiche Kante ist ein Beispielwert.")], related: ["targets", "tools", "animation"] },
  { id: "targets", group: "Erstellwerkzeuge", title: "Zielpeilungen und Winkelversatz", paragraphs: ["Zielmodi verändern die Richtung innerhalb eines Objekts. Sie gibt es beim Pinsel und im Modus mit konstantem Vektor der Formfüllung. Das Verschieben oder Animieren des Ziels ändert den Zielpunkt, ohne die Form neu zu zeichnen."],
    parameters: direction,
    steps: ["Wählen Sie Auf einen Punkt zu oder Von einem Punkt weg.", "Geben Sie Koordinaten ein oder verwenden Sie Auf der Karte wählen.", "Wählen Sie Großkreis oder Loxodrome.", "Lassen Sie Winkel relativ zum Ziel für direktes Zielen auf 0 oder geben Sie einen Versatz ein.", "Malen Sie und prüfen Sie mehrere Orte mit der Anzeige; Windfiedern zeigen die Richtung, aus der der Wind kommt."],
    images: [shot("create_tools/brush_tool_point", "Zielkoordinaten, Routenwahl und Winkelversatz.")], related: ["view", "brush", "fill", "measure"] },
  { id: "circle", group: "Erstellwerkzeuge", title: "Kreisstempel", paragraphs: ["Klicken Sie, um eine kreisförmige Strömung um den Zeiger zu setzen. Wählen Sie eine Scheibe, einen Ring oder eine Scheibe mit radialem Geschwindigkeitsverlauf. Der Winkel neigt die Strömung nach innen oder außen, ohne die gewählte Geschwindigkeit zu ändern."],
    parameters: [["Füllung: Gefüllt / Umriss / Gefüllt mit Verlauf", "Gefüllt malt die Scheibe mit der Geschwindigkeit. Umriss lässt ihre Mitte undefiniert. Gefüllt mit Verlauf verändert die Geschwindigkeit von der Mitte zum Rand."], ["Durchmesser / Ringbreite", "Außendurchmesser und Dicke des Umfangsbands. Beide verwenden die gewählte px- oder Grundeinheit."], speed, ["Geschwindigkeit (Mitte) / Geschwindigkeit (Rand)", "Endgeschwindigkeiten für Gefüllt mit Verlauf. Eine Mitte mit null ist definierte Stille, kein leeres Loch."], ["Drehung: Im Uhrzeigersinn / Gegen den Uhrzeigersinn", "Zirkulation im oder gegen den Uhrzeigersinn bei einem Tangentenwinkel von null."], ["Winkel zur Tangente", "Schieberegler von −90° bis +90°. −90° zeigt direkt nach innen, 0° folgt der Tangente, +90° zeigt nach außen. Zwischenwerte ergeben eine spiralförmige Strömung. Die Anzeige erfolgt in Grad."], feather, edge],
    images: [shot("create_tools/circle_tool", "Parameter des Kreises. Der Winkel zur Tangente verwendet jetzt einen Schieberegler von −90° bis +90°.")], related: ["tools", "divergence", "shape"] },
  { id: "fill", group: "Erstellwerkzeuge", title: "Formfüllung und Vektorverläufe", paragraphs: ["Malen Sie eine aufgezogene Vorlage oder ein Polygon. Die Umrisslinie bestimmt, wo Daten existieren; der Vektormodus bestimmt die Vektoren darin. Ein Verlauf mischt die Vektoren an den Enden, sodass unterschiedliche Endrichtungen auch die Geschwindigkeit dazwischen verändern können."],
    parameters: [["Form: Polygon / Quadrat / Rechteck / Kreis", "Klicken Sie die Eckpunkte des Polygons und schließen Sie mit der Eingabetaste oder einem Doppelklick ab. Ziehen Sie eine Vorlage auf. Esc bricht eine unfertige Konstruktion ab."], ["Form in", "Grundeinheiten legen eine geografische Geometrie fest; px verwendet die aktuelle zylindrische Bildschirmebene bzw. in Globus-, azimutalen und regionalen Ansichten eine örtliche Größe über Grund."], ["Vektormodus: Konstant / Verlauf", "Konstant verwendet eine Geschwindigkeit und den Richtungsmodus. Verlauf verteilt Start- und Endvektor über die Form."], speed, ...direction, ["Geschwindigkeit (Anfang) / Geschwindigkeit (Ende)", "Beträge an den gegenüberliegenden Enden des Verlaufs."], ["Richtung (Anfang) / Richtung (Ende)", "Richtungen an den Enden in der Konvention „aus“ / „nach“ des Projekts."], ["Verlaufsachse", "Geometrische Peilung vom Anfang des Verlaufs zu seinem Ende. Sie ist eine Achse, keine Richtung, aus der der Wind kommt."], feather, edge],
    images: [shot("create_tools/shape_fill", "Ein Polygon mit einem Vektorverlauf.")], related: ["targets", "shape", "selection"] },
  { id: "clone", group: "Erstellwerkzeuge", title: "Kopierstempel und Transparenz", paragraphs: ["Der Kopierstempel kopiert Vektoren, die in derselben Ebene unter ihm liegen, nicht aber die Basiskarte oder Hintergrundfarben. Löcher in der Quelle bleiben in der Vorschau und nach dem Loslassen transparent. Eine tatsächlich definierte Quelle mit Geschwindigkeit null wird weiterhin als Stille kopiert.", "Quellobjekte werden im aktuellen Bild berechnet, sodass ihre Änderungen und Animation den Kopierstempel verändern können. Objekte über dem Kopierstempel werden nicht zu seiner Quelle."],
    parameters: [brushShape, size, ["Quelle / Auf der Karte wählen", "Koordinaten des Quellankers. Wählen Sie sie, bevor Sie das Ziel malen."], ["Versatz: Ausgerichtet", "Behält den Versatz vom Zielanker zur Quelle bei. Bewegt sich die Abtaststelle, bewegt sich ihre Quelle entsprechend mit."], ["Versatz: Fest", "Beginnt das Abtasten für jeden Stempel entlang des Strichs wieder um die gewählte Quelle und trägt diesen Quellbereich so wiederholt auf."], feather, edge],
    steps: ["Aktivieren Sie die Ebene mit den Quellobjekten.", "Wählen Sie Kopierstempel und eine Quelle mit definierten Daten.", "Stellen Sie Größe, Versatzmodus und weiche Kante ein.", "Malen Sie das Ziel. Undefinierte Quellzellen lassen es unverändert."],
    images: [shot("create_tools/clone_stamp", "Quelle und Versatz bei einem kopierten Feld.")], related: ["layers", "tools", "troubleshooting"] },
  { id: "path", group: "Erstellwerkzeuge", title: "Kurve (Pfadwerkzeug)", paragraphs: ["Malen Sie einen Korridor für einen Jet, eine Front oder einen Kanal. Setzen Sie Routenpunkte und schließen Sie mit der Eingabetaste oder einem Doppelklick ab. Esc verwirft einen unfertigen Pfad. Die Strömung kann der Route folgen oder konstant bleiben."],
    parameters: [["Kurve: Polylinie / Bézier", "Polylinie verbindet die Eckpunkte mit geraden Segmenten. Bézier bietet gekrümmte Segmente und Kontrollgriffe."], ["Breite", "Volle Korridorbreite in px oder Grundeinheiten."], speed, ["Richtungsmodus: Konstant", "Eine Kompassrichtung über den gesamten Korridor. Frühere Versionen nannten dies Absolut; das Verhalten ist unverändert."], ["Richtungsmodus: Relativ zum Pfad", "Verwendet die örtliche Tangente. Richtung 0° folgt der Reihenfolge der Punkte, 180° strömt entgegen, 90° quer dazu."], ["Richtung", "Im Modus Konstant ein Kompasskurs in der Konvention des Projekts; im Modus Relativ zum Pfad ein geometrischer Versatz zur Tangente. Versätze werden nicht in Windrichtungen „aus“ umgerechnet."], feather, edge, eyedropper],
    images: [shot("create_tools/path_tool", "Ein Korridor, dessen Vektoren seiner Route folgen.")], related: ["tools", "shape", "animation"] },
  { id: "mask", group: "Bearbeitungswerkzeuge", title: "Maske", paragraphs: ["Eine Maske entfernt die Abdeckung früherer Daten in ihrer Ebene und legt tiefere Ebenen frei. Sie bleibt ein bearbeitbares, animierbares Objekt. Radieren entfernt Geometrie dagegen unwiderruflich."],
    parameters: [brushShape, size, feather, ["Umkehren", "Aus maskiert innerhalb der Grundfläche. Ein maskiert außerhalb und beschränkt die früheren Daten der Ebene auf diesen Bereich."], edge],
    images: [shot("edit_tools/mask_tool", "Eine Maske, die gemalte Formen kreuzt.")], related: ["eraser", "layers", "shape"] },
  { id: "intensity", group: "Bearbeitungswerkzeuge", title: "Verstärken / Abschwächen", paragraphs: [modifier, "Ändert die Geschwindigkeit bei gleichbleibender Richtung. Ein Nullvektor bleibt Stille."],
    parameters: [size, ["Stärke", "Schieberegler von −100 % bis +200 %. Null bewirkt nichts; +100 % verdoppelt die Geschwindigkeit; +200 % verdreifacht sie; −50 % halbiert sie; −100 % ergibt definierte Stille. Die weiche Kante blendet am Rand zur ursprünglichen Geschwindigkeit über."], feather],
    images: [shot("edit_tools/intensify_tool", "Erhöhen der Geschwindigkeit unter der Grundfläche eines Modifikators.")], related: ["divergence", "rotation", "layers"] },
  { id: "divergence", group: "Bearbeitungswerkzeuge", title: "Divergieren / Konvergieren", paragraphs: [modifier, "Divergieren lenkt die Strömung von der Mitte der Grundfläche oder der Mittellinie des Strichs weg; Konvergieren lenkt sie dorthin. Die Geschwindigkeit bleibt erhalten. Windfiedern zeigen in den ankommenden Wind: Ihre Schäfte können nach innen zeigen, wenn die tatsächliche Strömung divergiert.", "Bei nordwärts gerichteter Strömung östlich der Stempelmitte fügt Divergieren eine östliche Komponente hinzu, Konvergieren eine westliche."],
    parameters: [size, ["Stärke: Divergenz (nach außen)", "Die linke Seite lenkt die Strömung nach außen. Eine größere Stärke fügt eine stärkere radiale Komponente hinzu, bevor die ursprüngliche Geschwindigkeit wiederhergestellt wird."], ["Stärke: Konvergenz (nach innen)", "Die rechte Seite lenkt die Strömung nach innen. Die Mitte ist neutral. Der Prozentwert ist die Wirkungsstärke, keine Geschwindigkeitsänderung."], feather],
    images: [shot("edit_tools/convergence_divergence_tool", "Divergieren über Winddaten; Windfiedern zeigen die Richtung, aus der der Wind kommt.")], related: ["view", "circle", "rotation"] },
  { id: "rotation", group: "Bearbeitungswerkzeuge", title: "Bearbeitungswerkzeug Strömung drehen", paragraphs: [modifier, "Dreht die Vektoren an Ort und Stelle; ihre Grundfläche und räumlichen Merkmale bleiben, wo sie waren."],
    parameters: [size, ["Drehsinn: Im Uhrzeigersinn / Gegen den Uhrzeigersinn", "In welche Richtung die darunterliegende Strömung gedreht wird."], ["Stärke", "0° bis 180°. Null ist neutral, 90° dreht quer, 180° kehrt die Richtung um. Die Geschwindigkeit bleibt erhalten."], feather],
    images: [shot("edit_tools/rotation_tool", "Drehen der darunterliegenden Vektoren um 30°.")], related: ["selection", "warp", "intensity"] },
  { id: "warp", group: "Bearbeitungswerkzeuge", title: "Verformen und Verschieben", paragraphs: [modifier, "Verformen verlagert die Abtastpositionen, sodass sich Merkmale des Felds schieben oder verdrehen lassen. Verschieben arbeitet in zwei Schritten: Malen Sie mit dem Pinsel einen Bereich aus, lassen Sie los und ziehen Sie die Auswahl dann an ihre neue Position. Mit weicher Kante null bewegt sich das ausgewählte Feld unverändert; eine weiche Kante macht seinen inneren Rand weich und erhält den Kern. Beide Begrenzungen bleiben hervorgehoben, verbunden durch eine Linie zwischen ihren Mittelpunkten. Der geräumte Bereich und ein Band um das Ziel werden interpoliert, damit sie zum umgebenden Feld passen. Esc bricht die ausstehende Auswahl ab."],
    parameters: [size, ["Verformen: Schieben", "Verlagert das Feld in Richtung Schieben nach. Umschalt-Ziehen legt den Zug vom Anker zu seinem Ziel fest."], ["Schieben nach", "Zielkoordinaten, die für alle Bilder gelten. Schieben nach kann keine Schlüssel erhalten; Position kann die Platzierung des Objekts weiterhin animieren."], ["Verformen: Verdrehung", "Verdreht die Abtastung um den Anker."], ["Verdrehung", "Vorzeichenbehafteter Winkel von −360° bis +360°. Null ist neutral; das Vorzeichen ändert den Drehsinn."], ["Verschieben: Interpolationsabstand", "Wie weit die Interpolation über die Zielbegrenzung hinausreicht, in der px- oder geografischen Entfernungseinheit des Pinsels. Auch bei null wird der geräumte Quellbereich gefüllt."], ["Animation beim Verschieben", "Auswahlposition, Verschiebeposition (relativ), Weiche Kante und Interpolationsabstand haben eigene Spuren. Die Verschiebeposition hat gekoppelte Koordinaten mit gemeinsamen Schlüsseln und gemeinsamer Interpolation. Ziehen Sie die Quellauswahl mit gedrückter Umschalttaste, um ihr relatives Ziel mit Auto-Schlüssel zu setzen. Verschieben hat keine Formanimation."], feather],
    images: [shot("edit_tools/warp_tool", "Modus Verdrehung mit Größe, Winkel und weicher Kante.")], related: ["rotation", "selection", "shape"] },
  { id: "eraser", group: "Bearbeitungswerkzeuge", title: "Radierer und unwiderrufliche Schnitte", paragraphs: ["Radieren entfernt Geometrie aus Objekten oder Daten der aktiven Ebene. Es malt weder Hintergrund noch Werte mit Geschwindigkeit null. Rückgängig stellt den Schnitt wieder her; verwenden Sie eine Maske für einen eigenen, entfernbaren Ausschnitt.", "Schnitte bleiben entfernt, auch wenn sich animierte Umrisse ändern. Das Wählen des Radierers beendet die Formbearbeitung und blendet die Umrisspunkte aus."],
    parameters: [brushShape, size, feather], steps: ["Aktivieren und entsperren Sie die gewünschte Ebene.", "Wählen Sie Kreis oder Quadrat und eine Größe in px oder über Grund.", "Verwenden Sie weiche Kante 0 für einen sauberen Schnitt oder erhöhen Sie sie für einen weichen Übergang.", "Ziehen Sie über den unerwünschten Bereich. Rückgängig stellt ihn wieder her."],
    images: [shot("utility_tools/eraser", "Ein Radierer mit 400 Pixeln in Mercator.")], related: ["mask", "shape", "layers"] },
  { id: "animation", group: "Animation", title: "Schlüsselbilder und Bewegung", paragraphs: ["Der Abspielkopf wählt das Bild, das bearbeitet wird. Klappen Sie ein Objekt auf, um seine animierbaren Eigenschaften zu sehen. Rauten sind Schlüssel; zwischen ihnen folgen die Werte ihrer Interpolation. Gehen Sie zu einem Bild, fügen Sie eine Raute hinzu und bearbeiten Sie die Eigenschaften oder die Griffe auf der Karte.", "Auto-Schlüssel kann beim Bearbeiten Schlüssel anlegen. Richtungsmodi, die Füllung des Kreises, der Versatz des Kopierstempels, Umkehren der Maske sowie Modus und Schieben nach beim Verformen gelten für das ganze Objekt und können keine Schlüssel erhalten. Hat eine Eigenschaft Schlüssel, fügt eine Bearbeitung in einem anderen Bild einen Schlüssel hinzu, statt die ganze Animation zu ändern."],
    parameters: [["Wiedergabe / Pause / Stoppen", "Wiedergabe läuft vom aktuellen Bild weiter; Pause hält es an; Stoppen kehrt zum Anfang zurück."], ["Schleife", "Wiederholt die Wiedergabe nach dem letzten Bild."], ["Schritte/s", "Gewünschte Anzeigebilder pro Sekunde, unabhängig von den simulierten Stunden pro Bild. Nicht vorbereitete importierte Daten brauchen eventuell Zeit zum Laden."], ["Auto-Schlüssel", "Steuert das automatische Anlegen von Schlüsseln beim Bearbeiten animierbarer Eigenschaften."], ["Schritte", "Gesamtzahl der Bilder. Das Kürzen der Zeitleiste kann spätere Schlüssel entfernen und erfordert eine Bestätigung."], ["Zeit / Startzeit hinzufügen / ×", "Setzt oder entfernt die Startzeit in UTC. Ohne sie zeigt das Lineal relative Stunden; mit ihr stehen absolute UTC-Daten zur Verfügung."], ["Bereitschaftsleiste", "Zeigt vorbereitete Bilder. Große importierte Datensätze brauchen Zeit für die erste Vorbereitung."], ["Wertediagramm / Interpolation", "Klappen Sie eine Eigenschaft auf, um ihre Werte im Zeitverlauf zu prüfen. Klicken Sie mit der rechten Maustaste auf einen Schlüssel, um die Interpolation für den folgenden Abschnitt zu wählen."], ["Schlüsselauswahl", "Klicken Sie auf Schlüssel, um sie auszuwählen, ziehen Sie sie, um sie zu verschieben, und entfernen Sie sie mit Entf. Ausgewählte Schlüssel haben Vorrang vor dem Löschen von Objekten."]],
    images: [shot("overview/timeline", "Transport, Rate, Auto-Schlüssel, Zeit und Lebensdauerbalken."), shot("timeline/keyframes", "Eigenschaftsschlüssel und Punkte für Zwischenbilder.")],
    sections: [{ heading: "Mit konstanter Geschwindigkeit bewegen", paragraphs: ["Klicken Sie bei Position auf →+. Die Bewegung beginnt im ausgewählten Bild und endet am nächsten Positionsschlüssel oder, falls es keinen späteren Schlüssel gibt, im letzten Bild des Objekts."], parameters: [["Richtung nach (° rechtweisend)", "Fahrtrichtung: 0° Nord, 90° Ost, 180° Süd, 270° West. Immer „nach“, unabhängig von der Anzeige der Windrichtung „aus“."], ["Geschwindigkeit", "Fahrtgeschwindigkeit in der globalen Geschwindigkeitseinheit."], ["Bewegung hinzufügen / Abbrechen", "Erzeugt den Weg für das angegebene Intervall oder bricht ab. Vorhandene Schlüssel im Intervall werden erst nach Bestätigung ersetzt. Ein Rückgängig stellt die vorherige Spur wieder her."]], images: [shot("timeline/position_constant_motion", "Die Schaltfläche →+ bei Position."), shot("timeline/position_constant_motion_dialog", "Fahrtrichtung und Geschwindigkeit für das angegebene Intervall.")] }],
    related: ["spans", "shape", "links", "motion-vectors"] },
  { id: "spans", group: "Animation", title: "Lebensdauer eines Objekts: Start- und Endbild", paragraphs: ["Der Lebensdauerbalken legt die Bilder (einschließlich der Grenzen) fest, in denen ein Objekt beiträgt. Er ist unabhängig von den Animationsschlüsseln: Ein Objekt kann eine lange Bewegungsspur haben, aber nur während eines Teils davon aktiv sein."],
    parameters: [["Startgriff", "Ziehen Sie den linken Griff, um das erste aktive Bild festzulegen. Sein Klickbereich reicht über den dünnen gemalten Balken hinaus."], ["Endgriff", "Ziehen Sie den rechten Griff, um das letzte aktive Bild festzulegen."], ["Balkenkörper", "Ziehen Sie ihn, um das ganze Intervall bei gleicher Länge zu verschieben. Ein Klick ohne Bewegung wählt das Objekt aus."], ["Vorschau nach dem Loslassen", "Der Balken hält seine losgelassene Position, während die Dokumentzeilen aktualisiert werden, damit er nicht in den alten Bereich zurückspringt."]],
    images: [shot("timeline/keyframes", "Der Lebensdauerbalken liegt über den einzelnen Eigenschaftsspuren.")], related: ["animation", "macros", "shape"] },
  { id: "shape", group: "Animation", title: "Die Form eines Objekts animieren", paragraphs: ["Die Formanimation ist ein Bearbeitungsmodus für Erstell- und Bearbeitungsobjekte, ausgenommen aufgenommene Makros, Patches und Auswahlen von Verschieben. Umrisspunkte behalten ihre Identität zwischen den Schlüsseln und erscheinen nur, solange die Formschaltfläche des Objekts aktiviert ist."],
    steps: ["Wählen Sie das Objekt aus und klicken Sie auf das Umrisssymbol neben seinem Namen in der Zeitleiste.", "Ziehen Sie im gewünschten Bild die Punkte und fügen Sie bei Bedarf mit der Raute einen Formschlüssel hinzu.", "Gehen Sie zu einem anderen Bild und verschieben Sie die Punkte erneut.", "Fahren Sie durch die Zeitleiste, um den sich ändernden Umriss zu prüfen.", "Klicken Sie erneut auf das Umrisssymbol oder wählen Sie ein anderes Werkzeug, um den Modus zu verlassen und die Punkte auszublenden."],
    parameters: [["Umrisspunkte", "Positionen entlang des Umrisses im aktuellen Bild. Sie gehören zur Animation des Objekts und sind keine eigenen Objekte."], ["Formspur / Raute", "Speichert einen Umriss in einem Bild. Weitere Schlüssel legen Umrisse fest, zwischen denen interpoliert wird."], ["Zusammenspiel mit dem Radierer", "Schnitte bleiben unwiderruflich und werden nicht wiederhergestellt, nur weil sich der Umriss später ändert."]],
    images: [shot("timeline/shape_keyframes", "Umrisspunkte und eine Formspur mit Schlüsseln.")], related: ["animation", "eraser", "selection"] },
  { id: "links", group: "Animation", title: "Position oder Drehung verknüpfen", paragraphs: ["Eine Folgeverknüpfung lässt eine Eigenschaft der entsprechenden Eigenschaft eines Hauptobjekts folgen, sodass Merkmale sich gemeinsam bewegen oder drehen."],
    steps: ["Klappen Sie beide Objekte auf.", "Klicken Sie beim folgenden Objekt auf die Verknüpfungsschaltfläche von Position oder Drehung.", "Klicken Sie auf die Zeile des Hauptobjekts für diese Eigenschaft. Ein erneuter Klick auf die scharfgeschaltete Schaltfläche bricht ab.", "Bearbeiten Sie die Spur des Hauptobjekts. Klicken Sie auf die aktive Verknüpfung, um sie zu lösen, bevor Sie eine unabhängige Spur anlegen."],
    parameters: [["Verknüpfungsschaltfläche", "Schaltet eine Folgeverknüpfung scharf, meldet oder entfernt sie. Auch Ziehen zwischen einander entsprechenden Zeilen wird unterstützt."], ["Gefolgte Rauten", "Stellen die Animation des Hauptobjekts dar. Bearbeiten Sie sie in der Zeile des Hauptobjekts, statt sie als unabhängige Schlüssel des folgenden Objekts zu behandeln."]],
    images: [shot("timeline/link_motion_to_object", "Eine gefolgte Positionszeile mit dem Tooltip zum Lösen.")], related: ["animation", "motion-vectors"] },
  { id: "motion-vectors", group: "Animation", title: "Die Bewegung eines Objekts zu seinen Vektoren addieren", paragraphs: ["Das Bewegen einer Form und das Ändern ihrer gemalten Vektoren sind getrennte Entscheidungen. Der Bewegungsbeitrag addiert die Bewegung des Objekts zum Feld. Er erzeugt keinen Weg: Animieren Sie zuerst die Transformationen und aktivieren Sie dann ihre Beiträge.", "Bewegungsvektoren werden mit den ursprünglichen Vektoren kombiniert, sodass sich Geschwindigkeit und Richtung ändern können."],
    parameters: [["Bewegungsbeitrag (⇢)", "Addiert die zu dieser Transformation gehörende Bewegung. Position trägt die Fahrtgeschwindigkeit bei; verfügbare Beiträge von Skalierung und Drehung berücksichtigen deren sich ändernde Transformationen."], ["Konstante Bewegung (→+)", "Erzeugt einen Positionsweg. Das ist etwas anderes, als Bewegung zu gemalten Vektoren zu addieren."], ["Statische Transformation", "Eine Transformation, die sich nicht ändert, trägt keine Bewegung bei, auch wenn die Schaltfläche aktiv ist."]],
    images: [shot("timeline/add_motion_vectors", "Aktivierter Bewegungsbeitrag auf einer Positionsspur mit Schlüsseln.")], related: ["animation", "links", "macros"] },
  { id: "imports", group: "Daten und Makros", title: "GRIB, Zarr und Referenzbilder", paragraphs: ["GRIB- und Routing-Zarr-Importe fügen unterstützte Wind- und Strömungsfelder als getrennte Ebenen hinzu. Jedes Bild verwendet die Quellzeit, die diesem Projektschritt zugeordnet ist. Bilder sind visuelle Referenzen und enthalten keine exportierbaren Vektordaten."],
    parameters: [["Importieren", "Eine Schaltfläche für jede Datei, aus der eine Ebene werden kann. Der Dialog zeigt nur, was gelesen wird: GRIB2 (.grib2, .grb2, .grib, .grb), einen Routing-Zarr-Speicher, Bilder (.tif, .tiff, .png, .jpg, .jpeg) und GIS-Daten (.geojson, .json, .shp, .kml, .kmz, .gpx). Ein GeoTIFF wird zu einer Bildebene."], ["GRIB2-Datei", "Wählen Sie die Datei; Feld, Bilder, Pfad und Abdeckung sehen Sie in den Ebenendetails. Halten Sie sie beim erneuten Öffnen verfügbar."], ["Zarr-Speicher / Aus Zarr öffnen…", "Wählen Sie über Importieren die Datei zarr.json oben im Routing-Speicher; importiert wird ihr Verzeichnis. Wind und Strömung werden zu gewöhnlichen, bearbeitbaren Ebenen. Aus Zarr öffnen auf dem Startbildschirm wählt das Verzeichnis selbst und übernimmt außerdem Raster und Uhr des Projekts aus dem Speicher, innerhalb der Grenze von 240 Bildern. Halten Sie das ursprüngliche Verzeichnis beim erneuten Öffnen verfügbar."], ["Importierte Bildzellen", "Wählen Sie Bilder in der Zeitleistenzeile der Quellebene aus. Kopieren, Einfügen und Löschen wirken dann auf diese Bilder statt auf Objektschlüssel. Umschalt erweitert eine Folge."], ["Bild", "Wählen Sie ein Referenzbild und seine geografische Platzierung."], ["Bildgröße und -form", "Wählen Sie die Bildebene aus und verwenden Sie das Hand-Werkzeug. Ziehen Sie eine Ecke, um proportional zu skalieren, oder einen Seitengriff, um Breite oder Höhe zu dehnen. Die gegenüberliegende Ecke oder Seite bleibt fest. Ziehen Sie innerhalb des Bilds, um es zu verschieben. Rückgängig nimmt das ganze Ziehen zurück."], ["Bilddeckkraft", "Steuert, wie stark das Bild die Arbeitsfläche verdeckt."], ["Geschwindigkeitsfilter", "Beschränkt die Abdeckung des Felds auf einen zugelassenen Bereich; Bildfilter verwenden die Geschwindigkeit an den Bildpositionen."], ["Fehlende Datei", "Stellen Sie ihren referenzierten Pfad wieder her oder importieren Sie sie erneut. Fehlende Daten werden nicht als echte Stille behandelt."], ["Versetzte Ebene", "Auf einer Zeitleiste mit Startzeit wird eine Dateiebene, deren erstes Feld nicht zur Zeit des Schritts gilt, auf dem es liegt, in der Zeitleiste hervorgehoben, mit dem Versatz im Tooltip. Nichts wird blockiert, der Export bleibt unberührt. Die Schaltfläche neben dem Namen verschiebt die Felder auf die Schritte, für deren Zeiten sie gelten; ausgeblendete, eingefügte und radierte Schritte wandern mit. Ein Rückgängig stellt alles wieder her."]], related: ["history", "layers", "export"] },
  { id: "history", group: "Daten und Makros", title: "Historischen Wind und historische Strömungen herunterladen", paragraphs: ["Der Kalender im Ebenenbedienfeld öffnet den historischen Import. Wählen Sie UTC-Daten und Archive; jedes wird zu einer Ebene. Zwischengespeicherte Downloads können beim erneuten Aufrufen oder Wiederholen einer Anfrage wiederverwendet werden."],
    parameters: [["Beginn (UTC) / Ende (UTC)", "Einschließliche Endpunkte zu vollen Stunden. Längere Zeiträume bedeuten mehr Bilder und Downloads; prüfen Sie die Übersicht über den Aufwand."], ["Beginn der Zeitleiste setzen", "Richtet den Projektstart an der ersten angeforderten UTC-Zeit aus."], ["ERA5-Wind", "Wählt das angebotene Archiv für Wind in 10 m Höhe."], ["GlobCurrent", "Wählt das angebotene Archiv für die gesamte Oberflächenströmung."], ["Importieren / Abbrechen", "Startet die gewählte Anfrage oder lässt das Projekt vor dem Start unverändert."], ["Fortschritt", "Die Statusleiste meldet Herunterladen und Vorbereitung. Beide Archive oder längere Zeiträume erhöhen den Aufwand."], ["Download wiederholen", "Erscheint neben einem Fehler in der Statusleiste und wiederholt die gespeicherte Anfrage unter Verwendung zwischengespeicherter Daten. Das Bewegen auf der Karte blendet es nicht aus."]],
    images: [shot("layers/import_history", "UTC-Daten, Archivauswahl, Ausrichtung und Übersicht über den Aufwand.")], related: ["imports", "nrt", "animation", "capture", "troubleshooting"] },
  { id: "nrt", group: "Daten und Makros", title: "Wind und Strömungen in naher Echtzeit herunterladen", paragraphs: ["Die Schaltfläche mit der Antenne neben dem Kalender im Ebenenbedienfeld lädt die letzten Tage an Beobachtungsdaten bis jetzt für die angekreuzten Produkte und fügt für jedes eine Ebene hinzu. Geladene Daten werden auf den Datenträger geschrieben, sodass sich das Projekt danach offline öffnen lässt. Auf das Netzwerk wird nur zugegriffen, wenn Sie Importieren drücken.", "Die Produkte liegen etwa einen Tag hinter der Gegenwart zurück, daher sind die neuesten Schritte meist leer. Ein tägliches Produkt wie DUACS wird in jedem Schritt seines Tages angezeigt. Ein Produkt, das nicht geladen werden kann, wird in der Statusleiste genannt; die anderen kommen trotzdem an. Die Ebenen verhalten sich wie importierte GRIB-Ebenen: Geschwindigkeitsfilter, Radierer und Export gelten auch für sie. Ebenen der Meeresoberflächentemperatur sind die Ausnahme: Sie werden unter dem Feld gezeichnet und unter dem Zeiger angezeigt, aber nie gefiltert, radiert oder exportiert."],
    parameters: [["Tage", "Wie viele Tage vor heute (UTC) der Zeitraum um 00:00 beginnt; er endet immer jetzt. Die größte angebotene Zahl ist die, die eine Zeitleiste mit 240 Schritten bei der Schrittweite des Projekts fasst."], ["Beginn der Zeitleiste setzen / verschieben", "Versieht den ersten Schritt des Projekts mit dem Beginn des Zeitraums, damit die Datumsangaben der Zeitleiste zu den Daten passen. Es heißt verschieben, wenn das Projekt bereits eine Startzeit hat."], ["Zeitleiste verlängern", "Wird angeboten, wenn der Zeitraum mehr Schritte braucht, als das Projekt hat. Fügt Schritte hinzu, damit die Zeitleiste bis zur Gegenwart reicht; eine Zeitleiste wird nie gekürzt. Ohne Häkchen werden nur die Zeiten geladen, die die vorhandenen Schritte zeigen können."], ["Copernicus MULTIOBS", "Gesamte Oberflächenströmung — geostrophisch, windgetrieben und gezeitenbedingt — stündlich mit 0,25°."], ["Copernicus DUACS", "Geostrophische Oberflächenströmung aus Satellitenaltimetrie, täglich; wird in jedem Schritt ihres Tages angezeigt."], ["Copernicus-L4-Wind", "Aus Satelliten und Modell kombinierter Wind in 10 m Höhe, stündlich."], ["ASCAT Metop-B/C", "Scatterometer-Wind in 10 m von den beiden Metop-Satelliten, eine Ebene pro Tag mit den zusammengeführten Überflügen des Tages; kein Wert, wo kein Satellit vorbeikam."], ["CCMP NRT", "CCMP-Wind (Cross-Calibrated Multi-Platform) in 10 m, Version 2.1 Nahe-Echtzeit, 6-stündlich mit 0,25°, von Remote Sensing Systems, gelesen vom OceanWatch-Server der NOAA. Er reicht von 78° S bis 78° N; näher an den Polen wird nichts angezeigt."], ["NOAA Blended Seawinds", "NOAAs Verschnitt des Winds in 10 m aus allen Scatterometern und Radiometern im Orbit, 6-stündlich mit 0,25°, von NOAA CoastWatch. Jeder Tag ist eine Datei mit seinen vier Zeitpunkten und wird nur einmal heruntergeladen."], ["NOAA OISST", "Die optimal interpolierte Meeresoberflächentemperatur der NOAA, Version 2.1: täglich mit 0,25°, aus Satelliten, Schiffen und Bojen, bereitgestellt von NOAA NCEI. Fügt eine Ebene mit Meeresoberflächentemperatur hinzu."], ["NOAA Geo-Polar Blended", "Die von der NOAA zusammengeführte Meeresoberflächentemperatur geostationärer und polarumlaufender Satelliten, täglich, mit 0,25° von NOAA CoastWatch gelesen. Fügt eine Ebene mit Meeresoberflächentemperatur hinzu."], ["OSTIA (Met Office)", "Die operationelle Analyse von Meeresoberflächentemperatur und Meereis (OSTIA) des Met Office, täglich, mit 0,2° vom Copernicus Marine Service gelesen. Fügt eine Ebene mit Meeresoberflächentemperatur hinzu."], ["CMC", "Die tägliche Analyse der Meeresoberflächentemperatur des Canadian Meteorological Centre, mit 0,25° aus ihrem 0,1°-Gitter gelesen, aus dem PO.DAAC-Archiv der NASA. Fügt eine Ebene der Meeresoberflächentemperatur hinzu. Benötigt ein NASA-Earthdata-Token, das in den Einstellungen gesetzt wird; ohne eines ist sie ausgegraut."], ["NASA-Earthdata-Token", "Wird unter Einstellungen → NASA Earthdata gesetzt. Es liegt in einer eigenen Datei, wird nur beim Herunterladen von CMC an das PO.DAAC-Archiv der NASA gesendet und nie wieder angezeigt oder an einen KI-Client weitergegeben."], ["Ebene mit Meeresoberflächentemperatur", "Wird unter dem Feld farbig von −2 °C bis 32 °C gezeichnet, mit eigener Legende und der Temperatur unter dem Zeiger in der Anzeige. Nur zur Darstellung: Es wird nie darauf gemalt und sie wird nie exportiert. Die Einheit wird in den Einstellungen gewählt."], ["Aufwand", "Die Anzahl der Downloads und die ungefähre Größe auf dem Datenträger, vor dem Import angezeigt."]], related: ["history", "imports", "animation"] },
  { id: "capture", group: "Daten und Makros", title: "Ein Makro aufnehmen und in der Vorschau ansehen", paragraphs: ["Die Aufnahme zeichnet die Vektordaten eines Bereichs über mehrere Bilder auf, auf Wunsch einschließlich seiner Bewegung. Sie verwendet die aktive Feldart; Farben der Basiskarte und Bilder sind keine Vektordaten."],
    steps: ["Wählen Sie das Quellfeld und das erste Bild.", "Starten Sie den Aufnahmemodus, wählen Sie eine Form und zeichnen Sie den Bereich.", "Aktivieren Sie bei Bedarf Bewegung aufnehmen und klicken Sie dann auf Aufnahme starten.", "Gehen Sie zu späteren Bildern und verschieben Sie den Bereich so, dass er dem Merkmal folgt.", "Klicken Sie auf Aufnahme beenden, um das Makro in der Vorschau anzusehen.", "Verwenden Sie Makro bearbeiten, um es zu überarbeiten, Makro speichern…, um es zu benennen und abzulegen, oder Abbrechen, um es zu verwerfen."],
    parameters: [["Form", "Umriss des Bereichs, der die aufgenommenen Daten begrenzt."], ["Bewegung aufnehmen", "Behält die Bewegung des Aufnahmebereichs über die besuchten Bilder bei."], ["Aufnahmeschlüssel", "Positionen des Bereichs in den besuchten Schritten. Fahren Sie durch die Zeitleiste, um den Weg dazwischen zu prüfen."], ["Vorschau", "Spielt die aufgenommenen Daten für sich allein ab. Klicken Sie auf die Karte, um die Platzierung an anderer Stelle anzusehen."], ["Makro bearbeiten / Makro speichern / Abbrechen", "Überarbeiten, in der Bibliothek speichern oder die Aufnahme verwerfen. Andere Änderungen am Dokument sind während Aufnahme oder Vorschau gesperrt."]],
    images: [shot("creating_macros/create_macro_select_frame_and_area", "Erstes Bild und Bereich wählen."), shot("creating_macros/record_macro_end", "Den Bereich in einem späteren Bild verschieben."), shot("creating_macros/record_macro_preview", "Vorschau vor dem Speichern.")], related: ["macros", "animation", "history"] },
  { id: "macros", group: "Daten und Makros", title: "Makros einfügen und fehlende Bilder interpolieren", paragraphs: ["Wählen Sie Makro einfügen, dann einen Bibliothekseintrag, und klicken Sie, um ihn im aktuellen Bild zu platzieren. Der Umriss unter dem Zeiger zeigt die Platzierung nur in der ausgewählten gemalten Ebene. Ein durchgestrichener Zeiger bedeutet, dass das Makro keine Daten zur Wind- bzw. Strömungsart dieser Ebene hat oder die Ebene es nicht aufnehmen kann; in einer anderen Ebene wird kein Objekt platziert. Ein Makro mit beiden Feldern verwendet das passende Feld der ausgewählten Ebene. Es wird zu einem Objekt mit bearbeitbaren Transformationen und Lebensdauer.", "Die Interpolationsstrategie erscheint, wenn aufgenommene Bilder weiter auseinanderliegen als die Bilder des Projekts, etwa bei einem dreistündlichen Makro in einem stündlichen Projekt. Diese Strategie gilt für das ganze Makro und kann nicht animiert werden."],
    parameters: [["Makroauswahl / Aktualisieren", "Wählen Sie einen Bibliothekseintrag nach Name, Dauer, Bildzahl und Bewegungskennzeichen. Aktualisieren lädt den Inhalt der Bibliothek neu."], ["Bilder wiederholen", "Voreinstellung: Hält das letzte aufgenommene Bild bis zum nächsten."], ["Leere Bilder", "Zeigt in Zwischenbildern keine Makrodaten und legt frei, was darunter liegt."], ["Interpolieren", "Mischt u und v getrennt und interpoliert die aufgezeichnete Bewegung. Die Interpolation nach Komponenten verhindert, dass eine Richtung am Übergang der Peilung eine volle Umdrehung macht."], ["Schleife", "Wiederholt die aufgenommene Folge innerhalb der aktiven Lebensdauer des Objekts."], feather, edge, ["Bibliotheksverzeichnis", "Wird in den Einstellungen festgelegt. Eingefügte Makros behalten ihre eigenen Bilder im Projekt, sodass das Löschen der Bibliothek bereits eingefügte Makros nicht entfernt."]],
    images: [shot("creating_macros/insert_macro_hover", "Der Einfügeumriss folgt dem Zeiger."), shot("creating_macros/insert_macro_clicked", "Ein eingefügtes Makro und sein Lebensdauerbalken.")], related: ["capture", "spans", "motion-vectors", "settings"] },
  { id: "measure", group: "Messungen", title: "Vergleich von Großkreis und Loxodrome", paragraphs: ["Wählen Sie unter Messen Großkreis / Loxodrome und klicken Sie zwei Endpunkte an. Der Großkreis ist die kürzeste Route auf der Kugel mit sich ändernder örtlicher Peilung. Eine Loxodrome hält einen konstanten Kurs und ist in der Regel länger."],
    parameters: [["Beschriftung GC", "Entfernung und Anfangskurs der Großkreisroute."], ["Beschriftung RL", "Entfernung und konstanter Kurs der Loxodrome."], ["Endpunkte", "Ziehen Sie sie, um den Vergleich anzupassen."], ["Alt-Klick auf einen Punkt", "Entfernt diese Messung."], ["Großkreis / Loxodrome löschen", "Entfernt alle Routenvergleiche und behält die übrigen Messungen."], ["Alle löschen", "Entfernt alle Messungen, nicht aber Vektorobjekte."]],
    images: [shot("global_utility_tools/great_circle_rhumb_line", "Großkreisbogen und gestrichelte Loxodrome zwischen denselben Endpunkten.")], related: ["targets", "rings", "dividers"] },
  { id: "rings", group: "Messungen", title: "Entfernungsringe", paragraphs: ["Wählen Sie Entfernungsringe und klicken Sie einen Mittelpunkt an. Die Ringe stellen Entfernungen über Grund dar, daher kann eine Projektion ihr Aussehen verzerren."],
    parameters: [["Abstand", "Entfernung über Grund zwischen den Ringen in der globalen Entfernungseinheit."], ["Ringe", "Anzahl der Ringe. Der äußere Radius ist Abstand × Ringe."], ["Den letzten Satz bearbeiten", "Änderungen wirken auf den aktiven Satz. Klicken Sie anderswo, um einen weiteren Satz hinzuzufügen; ziehen Sie einen Mittelpunktgriff, um ihn zu verschieben."], ["Alt-Klick auf einen Punkt", "Entfernt diesen Ringsatz."], ["Entfernungsringe löschen / Alle löschen", "Löscht die Ringsätze oder alle Messarten."]],
    images: [shot("global_utility_tools/range_rings", "Zwanzig Ringe im Abstand von 50 nm mit einem äußeren Radius von 1000 nm.")], related: ["measure", "dividers", "settings"] },
  { id: "dividers", group: "Messungen", title: "Stechzirkel und Entfernungen über mehrere Schläge", paragraphs: ["Wählen Sie Stechzirkel und klicken Sie nacheinander Wegpunkte an. Jeder Schlag zeigt Entfernung und Kurs; die Kette meldet die aufsummierte Entfernung. Messungen verändern die exportierten Vektoren nicht."],
    parameters: [["Klick", "Fügt einen Schlag ab dem letzten Wegpunkt hinzu."], ["Eingabetaste / Esc", "Beendet die aktuelle Kette."], ["Wegpunktgriffe", "Ziehen Sie sie, um die Route anzupassen und die Entfernungen neu zu berechnen."], ["Alt-Klick auf einen Punkt", "Entfernt diese Messung."], ["Stechzirkel löschen / Alle löschen", "Löscht die Ketten oder alle Messungen."]],
    images: [shot("global_utility_tools/dividers", "Eine Kette aus mehreren Schlägen mit Kursen und Gesamtentfernungen.")], related: ["measure", "rings"] },
  { id: "feature-speed", group: "Messungen", title: "Geschwindigkeit und Richtung eines ziehenden Systems", paragraphs: ["Wählen Sie unter Messen die Verlagerungsgeschwindigkeit, um zu erfahren, wie schnell und wohin ein Tief, eine Front oder ein Wirbel zieht. Klicken Sie auf das System, stellen Sie die Zeitleiste auf einen späteren Zeitschritt und klicken Sie es erneut an. Die Linie zwischen den beiden Markierungen wird mit der mittleren Geschwindigkeit in der globalen Geschwindigkeitseinheit und dem Kurs des Systems beschriftet; Entfernung und verstrichene Zeit stehen neben der zweiten Markierung.", "Zwischen den beiden Klicks läuft die Zeitleiste nur vorwärts: Frühere Schritte sind abgeblendet, und das Fahren über das Lineal, die Schritttasten und die Wiedergabe halten am Schritt der ersten Markierung an. Die Richtung ist ein Kurs – wohin das System zieht –, gleich welche Richtungskonvention das Projekt für seinen Wind verwendet. Messungen verändern die exportierten Vektoren nicht."],
    parameters: [["Erster Klick", "Markiert, wo sich das System im aktuellen Zeitschritt befindet, und verhindert, dass die Zeitleiste zurückgeht."], ["Zweiter Klick", "Markiert in einem späteren Zeitschritt, wohin sich das System verlagert hat, und schließt die Messung ab."], ["Esc / Abbrechen", "Verwirft die erste Markierung und gibt die Zeitleiste frei."], ["Beschriftungen", "Mittlere Geschwindigkeit und Kurs entlang der Linie; Entfernung und verstrichene Stunden neben der zweiten Markierung."], ["Markierungsgriffe", "Ziehen Sie eine der Markierungen, um die Messung anzupassen. Die Zeitschritte bleiben, wie sie angeklickt wurden."], ["Alt-Klick auf einen Punkt", "Entfernt diese Messung."], ["Verlagerungsgeschwindigkeiten löschen / Alle löschen", "Löscht diese Messungen oder alle Messungen."]], related: ["dividers", "measure", "animation"] },
  { id: "settings", group: "Einstellungen und Export", title: "Designs, Einheiten, Pfeile und Windfiedern", paragraphs: ["Öffnen Sie die Einstellungen über das Zahnrad oder die Schaltfläche Einstellungen auf der Startseite. Der Abschnitt Darstellung bietet unter Design Original (Mitternacht), Salbei & Petrol, Ozean, Pflaume, Glut und Papier sowie ein eigenes Design. Designs wirken sofort in der ganzen Anwendung und bleiben unabhängig von Projekten erhalten. Einheiten und Symbolstile sind Einstellungen der Anwendung; Farbskalen und Farbverläufe werden im Projekt gespeichert. Darstellungsentscheidungen ändern weder exportierte Beträge noch Richtungen."],
    parameters: [["Entfernung: km / nm", "Rechnet Eingaben und Anzeigen zwischen Kilometern und Seemeilen um."], ["Geschwindigkeit: kt / mph / km/h", "Rechnet Werkzeugwerte, Anzeigen, Legenden und Bewegungsdialoge um. Die Werte werden umgerechnet, nicht umgedeutet."], ["Temperatur: °C / °F", "Rechnet die Meeresoberflächentemperatur in Legende und Anzeige um. Die Ebene enthält °C; nur die Darstellung ändert sich."], ["Pfeile / Windfiedern", "Getrennte Stileinstellungen und Vorschauen für jede Symbolart."], ["Größe (%)", "Symbollänge in Prozent der normalen Bildschirmgröße, von 25 % bis 300 %."], ["Dichte (%)", "Anzahl und Abstand der Symbole. Eine höhere Dichte zeigt mehr örtliche Richtungen, kann die Karte aber überfüllen."], ["Linienstärke (px)", "Stärke von Schaft und Fiedern."], ["Farbe / Deckkraft (%)", "Symbolfarbe und Gesamttransparenz."], ["Nach Geschwindigkeit abblenden", "Senkt die Deckkraft in langsamerer Strömung, lässt definierte Windstille aber sichtbar."], ["Schlagschatten", "Fügt hinter den Symbolen Kontrast hinzu."], ["Schattenfarbe / Schattendeckkraft (%)", "Eigene Farbe und Transparenz für den Schatten."], ["Schatten X / Y (px)", "Waagerechter und senkrechter Versatz des Schattens in Pixeln."], ["Pfeile zurücksetzen / Windfiedern zurücksetzen", "Stellt das voreingestellte Aussehen dieses Stils wieder her."], ["Farbskalen des Projekts", "Feste Höchstgeschwindigkeiten für Wind und Strömung, wenn die automatische Skala aus ist."], ["Farbverläufe des Projekts", "Getrennte Farbverläufe für Wind und Strömung, ausgewählt aus Farbfeldern."], ["Voreinstellungen für neue Projekte", "Anfängliche Skalengrenzen für Wind und Strömung in später erstellten Projekten."], ["Tastenkürzel", "Klicken Sie auf eine Belegung und drücken Sie dann die neue Tastenkombination. Die angezeigten Belegungen beschreiben Ihre aktuelle Einrichtung."], ["Automatisches Speichern / Makrobibliothek", "Wählen Sie Momentaufnahme zur Wiederherstellung, direktes Speichern oder manuelles Speichern. Legen Sie das Bibliotheksverzeichnis fest oder löschen Sie Bibliothekseinträge. Das Löschen aus der Bibliothek fragt nach einer Bestätigung und behält bereits in Projekte eingefügte Makros."], ["MCP-Dienst", "Erlaubt einem KI-Client auf diesem Computer, die Anwendung über das Model Context Protocol zu steuern. Standardmäßig aus; eingeschaltet zeigt der Abschnitt die lokale Adresse und das Token. Zu Claude Code hinzufügen und Zu Codex hinzufügen tragen den Dienst in die Konfiguration dieses Clients ein; nach einem erneuerten Token oder einem geänderten Port aktualisiert ihn dieselbe Schaltfläche. Zu Claude Desktop hinzufügen öffnet eine VectorEffects-Erweiterung im Installationsprogramm von Claude Desktop, wo Sie sie bestätigen; sie wird einmal installiert und folgt einem neuen Token oder Port von selbst. Die Konfiguration für andere Clients enthält dasselbe als Text zum Kopieren. Token erneuern widerruft das alte. Die Statusleiste zeigt MCP und das zuletzt verwendete Werkzeug, solange ein Client verbunden ist. Was ein KI-Client ohne Nachfrage tun darf, wird über den Hinzufügen-Schaltflächen gewählt: Standardmäßig läuft alles, was in VectorEffects bleibt und sich rückgängig machen lässt, ohne Nachfrage, während Speichern, Exportieren, Herunterladen und Verwerfen weiterhin nachfragen. Die Wahl gilt, sobald eine Hinzufügen-Schaltfläche geklickt wird."]],
    images: [{ path: "settings.png", caption: "Getrennte Einstellungen für das Aussehen von Pfeilen und Windfiedern." }], related: ["view", "projects", "macros"] },
  { id: "export", group: "Einstellungen und Export", title: "GRIB2 exportieren", paragraphs: ["GRIB exportieren… schreibt die berechneten Vektoren für andere Anwendungen. Der Dialog fragt nach Ziel und Bezugszeit der Vorhersage. Die Auswahl von Ursprungszentrum und Genauigkeit wurde entfernt. Jede Meldung enthält „Created with VectorEffects“.", "Der Export verwendet das Projektgitter, unabhängig von Zoom, Bildschirmgröße und Symboldichte. Bewahren Sie die .veproj-Datei auf, um weiter zu bearbeiten."],
    parameters: [["Ziel", "Pfad der .grib2-Ausgabedatei."], ["Vorhersagebeginn (UTC)", "Bezugszeit der Vorhersage aus Jahr, Monat, Tag und Stunde. Die Versätze der Bilder werden addiert, um die Gültigkeitszeiten der Meldungen zu erhalten; prüfen Sie sie gegen den beabsichtigten historischen oder Vorhersagezeitraum."], ["Geschätzte Größe", "Eine Obergrenze. Dünn besetzte und konstante Felder können deutlich kleiner sein."], ["Speicherort wählen und exportieren… / Fortschritt / Export abbrechen", "Startet den Export und meldet ihn oder beendet ihn, ohne das Projekt zu verändern."], ["Undefinierte Daten", "Nicht abgedeckte Zellen verwenden GRIB-Bitmaps. Sie werden nicht als null geschrieben. Bewusst gemalte Stille bleibt eine definierte Null."], ["Wind und Strömung", "u und v werden für jedes Bild und jede sichtbare Feldart getrennt geschrieben. Ausgeblendete Ebenen tragen nicht bei."], ["Vermerk", "Jede Meldung enthält „Created with VectorEffects“ in ihrem Abschnitt für lokale Verwendung. Ein Lesegerät zeigt dies in den gewöhnlichen Vorhersageansichten möglicherweise nicht an."], ["Automatische Packung", "Standardmäßige einfache 16-Bit-Packung mit kompakten konstanten Feldern. Eine Wahl der Genauigkeit ist nicht nötig."], ["Ausgeschlossene Ansichtsinhalte", "Basiskarte, Bilder, Symbole, Auswahlgriffe und Messungen werden nicht zu Vektoren."], ["Zarr exportieren…", "Schreibt dieselben berechneten Vektoren stattdessen als Zarr-V3-Verzeichnis im Routing-Layout: ein Float16-Datenarray aus u10, v10, ucur und vcur mit den Koordinaten time, param, latitude und longitude, Breite ab 90° und Länge ab -180°. Die Chunks umfassen drei Tage mal 10 Grad, sind mit Zstd komprimiert und in Shards nach Ozeanbecken gebündelt; nicht abgedeckte Zellen sind NaN, und ein Bereich ohne Inhalt wird gar nicht geschrieben."]],
    images: [{ path: "export.png", caption: "Der vereinfachte Exportdialog mit UTC-Bezugszeit und Zielauswahl." }],
    related: ["projects", "layers", "imports", "troubleshooting"] },
  { id: "troubleshooting", group: "Einstellungen und Export", title: "Fehlerbehebung", paragraphs: ["Prüfen Sie zuerst die aktive Ebene, das ausgewählte Bild und die Feldart. Rückgängig hilft, eine kürzliche Änderung einzugrenzen. Speichern Sie eine Kopie, bevor Sie ein komplexes Projekt untersuchen."],
    parameters: [["Nichts erscheint", "Prüfen Sie Sichtbarkeit, Sperre, Lebensdauer des Objekts und Geschwindigkeitsfilter. Bearbeitungswerkzeuge brauchen definierte Daten unter sich. Eine neutrale Stärke oder eine Auswahl von Verschieben ohne Verschiebung bewirkt nichts."], ["Erster Klick nach einer Einstellung", "Der nächste gewöhnliche Klick übernimmt die Zahleneingabe und verwendet das Werkzeug. Auf der Karte wählen, Aufnahme und Pipette reservieren den Klick für ihre angezeigte Aktion."], ["Leerer Kopierstempel", "Die Quellvektoren müssen in derselben Ebene unter dem Kopierstempel liegen. Eine leere Quelle bleibt transparent; definierte Stille wird weiterhin kopiert."], ["Divergieren wirkt umgekehrt", "Windfiedern zeigen in den ankommenden Wind. Divergieren lenkt die tatsächliche Strömung nach außen, Konvergieren nach innen."], ["Objekt nicht mehr im Projekt", "Rückgängig oder Löschen kann die Auswahl aufheben. Veraltete Auswahlen und Antworten der Eigenschaften werden jetzt verworfen. Schlägt eine tatsächliche Änderung trotzdem fehl, wählen Sie die aktuelle Zeile des Objekts erneut aus."], ["Langsame Wiedergabe importierter Daten", "Warten Sie auf die Bereitschaftsleiste. Das erste Lesen der Archive und die Berechnung können die gewünschten Schritte/s verzögern."], ["Historischer Download fehlgeschlagen", "Verwenden Sie Download wiederholen neben der Fehlermeldung. Prüfen Sie den angeforderten Zeitraum und die Verbindung, wenn das Archiv weiterhin nicht verfügbar ist."], ["Fehlende Quelle / zuletzt verwendetes Projekt", "Stellen Sie den referenzierten Pfad wieder her oder suchen Sie die Datei mit Öffnen / Importieren erneut. Fehlende Projektpfade werden aus der Liste der zuletzt verwendeten entfernt."], ["Ablauf der Beta", "Diese Beta läuft laut Systemdatum am 1. Januar 2027 ab. Installieren Sie eine aktualisierte Version, um weiterzuarbeiten."]],
    related: ["layers", "clone", "divergence", "history", "export"] },
];

export default topics;
